/** The page's icon set: 'phosphor' (recommended) or 'lucide' (today's look, the plugin's current set). */
let ICON_SET = (typeof localStorage !== 'undefined' && localStorage.getItem('ev-icon-set')) || 'phosphor';

function ICON(name, size = 16, opts = {}) {
	const s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
	let markup, vb = 256, world = false;
	if (name.startsWith('gi-') && ICON_WORLD[name]) { markup = ICON_WORLD[name][0]; vb = 512; world = true; }
	else {
		const w = opts.weight && opts.weight !== 'bold' && typeof ICON_COMPARE !== 'undefined' && ICON_COMPARE.ph[opts.weight] ? ICON_COMPARE.ph[opts.weight][ICON_UI_NAME(name)] : null;
		markup = w || ICON_UI[name];
		while (markup && markup[0] === '@') markup = ICON_UI[markup.slice(1)];
	}
	if (!markup) markup = '';
	const nd = !world && !opts.raw && ICON_NUDGE[name];
	s.setAttribute('viewBox', nd ? `${nd[0]} ${nd[1]} ${vb} ${vb}` : `0 0 ${vb} ${vb}`);
	s.setAttribute('width', size); s.setAttribute('height', size);
	s.setAttribute('fill', 'currentColor');
	s.setAttribute('class', 'ev-i' + (world ? ' ev-gi' : '') + (opts.cls ? ' ' + opts.cls : ''));
	s.dataset.icon = name;
	if (opts.title) { s.setAttribute('role', 'img'); s.setAttribute('aria-label', opts.title); } else s.setAttribute('aria-hidden', 'true');
	s.innerHTML = markup;
	return s;
}
/** Which Phosphor name an ICON name draws (for the comparison table). */
function ICON_UI_NAME(name) { return ICON_PH_NAMES[name] || name; }
const ICON_PH_NAMES = {"drop":"drop","first-aid":"first-aid","tag-bold":"tag","book-bold":"book-open","shield":"shield","damage":"drop","heal":"first-aid","condition":"tag","statblock":"book-open","temp":"shield-plus","save":"shield-check","concentration":"brain","poison":"flask","attack":"sword","spell":"magic-wand","order":"list-numbers","edit":"pencil-simple","roll":"dice-five","chevron-left":"caret-left","chevron-right":"caret-right","chevron-down":"caret-down","next":"skip-forward","undo":"arrow-counter-clockwise","plus":"plus","minus":"minus","users":"users","more":"dots-three","heart":"heart","heart-crack":"heart-break","swords":"sword","dice":"dice-five","flame":"fire","clock":"clock","hourglass":"hourglass","target":"target","skull":"skull","check":"check","x":"x","search":"magnifying-glass","grip":"dots-six-vertical","crosshair":"crosshair-simple","crown":"crown","castle":"castle-turret","eye":"eye","zap":"lightning","droplet":"drop","flag":"flag","sparkle":"sparkle","timer":"timer","reaction":"arrow-arc-left","arrow-right":"arrow-right","arrow-up":"arrow-up","book":"book-open","delete":"backspace","play":"play","list":"list","link":"link","tag":"tag","panel":"sidebar-simple","wand":"magic-wand","moon":"moon","footprints":"footprints","hand":"hand","lock":"lock","feather":"feather","sun":"sun","activity":"pulse","bandage":"bandaids","sliders":"sliders-horizontal","bed":"bed","heartbeat":"heartbeat","users-three":"users-three"};
/** Optical centring: where a glyph's ink sits off the middle of its box (viewBox units, measured in headless Chrome
    by getBBox), the viewBox moves so the ink is centred. Drops, play triangles and shields keep their drawn position:
    their mass sits low or to one side on purpose. */
const ICON_NUDGE = {"tag-bold": [12, 12], "book-bold": [0, 16], "condition": [12, 12], "statblock": [0, 16], "concentration": [0, -4], "poison": [0, -4], "spell": [12, 0], "order": [0, -4], "edit": [4, -4], "chevron-left": [-8, 0], "chevron-right": [8, 0], "chevron-down": [0, 8], "undo": [-8, 0], "heart": [0, 8], "heart-crack": [0, 8], "flame": [0, -4], "skull": [0, -4], "check": [4, 8], "crown": [0, -12], "castle": [0, 4], "flag": [8, 4], "sparkle": [4, -4], "timer": [0, -8], "reaction": [-4, 8], "book": [0, 16], "delete": [-8, 0], "tag": [12, 12], "wand": [12, 0], "moon": [5.9, -6], "hand": [-8, 0], "lock": [0, -12], "feather": [4, -4], "activity": [0, -4], "bed": [6, 0], "heartbeat": [0, 8], "users-three": [0, 8.3], "shield": [0, 12], "temp": [0, 12], "save": [0, 12]};
function hasICON(name) { return !!(ICON_UI[name] || ICON_WORLD[name]); }


/* Damage types as icons (Phosphor Bold): the dice say how much, the icon says what kind. Every game's
   damage words map here; the word stays in the tooltip and for screen readers. */
const DMG_ALIAS = {
	fire: 'fire', cold: 'cold', lightning: 'lightning', electricity: 'lightning', thunder: 'thunder', sonic: 'thunder',
	acid: 'acid', poison: 'poison', necrotic: 'necrotic', void: 'necrotic', negative: 'necrotic', radiant: 'radiant', vitality: 'radiant', positive: 'radiant',
	psychic: 'psychic', mental: 'psychic', force: 'force', spirit: 'force', piercing: 'piercing', pierc: 'piercing', p: 'piercing',
	slashing: 'slashing', slash: 'slashing', s: 'slashing', bludgeoning: 'bludgeoning', bludg: 'bludgeoning', b: 'bludgeoning',
	phy: 'slashing', physical: 'slashing', mag: 'force', magic: 'force', magical: 'force',
};
const DMG_LABEL = { fire: 'Fire', cold: 'Cold', lightning: 'Lightning', thunder: 'Thunder', acid: 'Acid', poison: 'Poison', necrotic: 'Necrotic', radiant: 'Radiant', psychic: 'Psychic', force: 'Force', piercing: 'Piercing', slashing: 'Slashing', bludgeoning: 'Bludgeoning' };
/** The icon for a damage word ("fire", "pierc.", "phy"); null for an unknown one. Pass label to use the game's own word in the tooltip. */
function dmgIcon(word, size = 15, label) {
	const key = DMG_ALIAS[String(word || '').toLowerCase().replace(/[^a-z]/g, '')];
	if (!key) return null;
	const el = ICON('dmg-' + key, size);
	const t = (label || DMG_LABEL[key]) + ' damage';
	el.setAttribute('role', 'img'); el.setAttribute('aria-label', t);
	const tt = document.createElementNS('http://www.w3.org/2000/svg', 'title'); tt.textContent = t; el.prepend(tt);
	return el;
}
